from common_r2 import *
from t2_r2 import quantile
def main():
 q=read(R/'13_numerical_qualification/QUALIFICATION_DECISION.json');assert q['qualified'];p=R5/'11_ml_dataset'/SID;hc=np.load(p/'surface_coordinates.npz');ha=np.load(p/'surface_area_weights.npz')['area_mm2'];ht=np.load(p/'T2_regularized_stress.npz');tri=np.load(p/'surface_triangles.npz')['triangles'];f=np.load(R/'13_numerical_qualification/COMPARISON_FIELDS.npz');n=len(f['xyz']);front=hc['face_label']==0;ix=np.flatnonzero(front);assert len(ix)==n and np.array_equal(hc['xyz'][front],f['xyz']) and np.allclose(ha[front],f['area'],rtol=5e-16,atol=0);assert np.array_equal(hc['source_ids'][front],f['source_ids']);source_tri=np.load(R/'01_protocol_freeze/R1_frozen/source/triangles.npy');assert np.array_equal(tri[np.all(front[tri],axis=1)],source_tri)
 a=ht['sigma1_MPa'][front];b=f['M2'];w=f['area'];mask=f['common']&ht['valid'][front]&np.isfinite(a);coverage=float(w[mask].sum()/w[f['core']].sum());assert coverage>=.99;qa=quantile(a[mask],w[mask],.95);qb=quantile(b[mask],w[mask],.95);h1=mask&(a>=qa);h2=mask&(b>=qb);delta=b-a;oldbc=read(p/'mechanical_conditions.json');out=dict(status='DESCRIPTIVE_JOINT_BVP_GEOMETRY_CONTRAST_ONLY',points=int(mask.sum()),common_area_mm2=float(w[mask].sum()),common_core_coverage=coverage,historical_mean_MPa=float(np.average(a[mask],weights=w[mask])),V1_mean_MPa=float(np.average(b[mask],weights=w[mask])),mean_delta_MPa=float(np.average(delta[mask],weights=w[mask])),MAE_MPa=float(np.average(abs(delta[mask]),weights=w[mask])),RMSE_MPa=float(np.sqrt(np.average(delta[mask]**2,weights=w[mask]))),relative_L2_to_historical=float(np.sqrt(np.sum(w[mask]*delta[mask]**2)/np.sum(w[mask]*a[mask]**2))),high95_IoU=float(w[h1&h2].sum()/w[h1|h2].sum()),historical_Q95_MPa=qa,V1_Q95_MPa=qb,historical_loadline_Z_mm=oldbc['common_load_line'][2],V1_loadline_Z_mm=float(case_origin()[2]),loadline_delta_Z_mm=float(case_origin()[2])-oldbc['common_load_line'][2],source_XYZ_exact=True,source_IDs_exact=True,T0_triangles_exact=True,T0_weights_exact=False,T0_weights_max_roundoff_mm2=float(abs(ha[front]-w).max()),T0_weights_max_relative_roundoff=float((abs(ha[front]-w)/w).max()),comparison_weights='Unchanged V1frozen originalT0areas; historicalT0differs only summationroundoff' ,historical_radius_mm=float(ht['radius_mm']),historical_distance=str(ht['distance']),no_causal_rear_only_attribution=True,no_AI_prediction=True)
 write(R/'14_historical_comparison/HISTORICAL_COMPARISON.json',out);table(R/'14_historical_comparison/HISTORICAL_VS_V1_METRICS.csv',[out]);np.savez_compressed(R/'14_historical_comparison/HISTORICAL_FIELDS.npz',xyz=f['xyz'],source_ids=f['source_ids'],area=w,common=mask,historical=a,V1=b,delta_MPa=delta,high_historical=h1,high_V1=h2)
 write(R/'14_historical_comparison/HISTORICAL_INPUT_HASHES.json',{str(z):sha(z) for z in [p/'surface_coordinates.npz',p/'surface_area_weights.npz',p/'surface_triangles.npz',p/'T2_regularized_stress.npz',p/'surface_validity_masks.npz',p/'mechanical_conditions.json',p/'qualification_report.json']});print('HISTORICAL',out,flush=True)
if __name__=='__main__':protect();main()


